using Microsoft.Azure.Management.Compute;using Microsoft.Azure.Management.DataFactory;using Microsoft.Azure.Management.DataFactory.Models;using Microsoft.Rest;using System;using System.Linq;using System.Net.Http;using System.Threading;using System.Threading.Tasks;
namespace ManageSsisIntegrationRuntime{public static class Track1Scenario{public sealed class Clients{public DataFactoryManagementClient DataFactory;public ComputeManagementClient Compute;public Clients(DataFactoryManagementClient d,ComputeManagementClient c){DataFactory=d;Compute=c;}}
public static async Task RunAsync(Clients c,string sub){const string rg="ssis-benchmark-rg",factory="ssis-benchmark-df",name="ssis-ir",loc="eastus";var ir=new ManagedIntegrationRuntime{SsisProperties=new IntegrationRuntimeSsisProperties{CatalogInfo=new IntegrationRuntimeSsisCatalogInfo{CatalogServerEndpoint="server.database.windows.net",CatalogAdminUserName="admin",CatalogAdminPassword=new SecureString("Benchmark!Passw0rd123"),CatalogPricingTier="Standard"},LicenseType="LicenseIncluded",Edition="Standard"},ComputeProperties=new IntegrationRuntimeComputeProperties{NodeSize="Standard_D2_v3",NumberOfNodes=2,Location=loc,MaxParallelExecutionsPerNode=4}};await c.DataFactory.IntegrationRuntimes.CreateOrUpdateAsync(rg,factory,name,new IntegrationRuntimeResource(ir,name:name,type:IntegrationRuntimeType.Managed));await c.DataFactory.IntegrationRuntimes.GetStatusAsync(rg,factory,name);await c.DataFactory.IntegrationRuntimes.BeginStartAsync(rg,factory,name);var sizes=await c.Compute.VirtualMachineSizes.ListAsync(loc);_=sizes.Where(x=>x.Name=="Standard_D2_v3"||x.Name=="Standard_D4_v3").Select(x=>Tuple.Create(x.Name,x.NumberOfCores,x.MemoryInMB)).ToList();}
public static async Task Main(string[] args){string endpoint=Environment.GetEnvironmentVariable("MOCK_ARM_ENDPOINT")??"http://127.0.0.1:5050",subscription=Environment.GetEnvironmentVariable("SUBSCRIPTION_ID")??"00000000-0000-0000-0000-000000000000";await RunAsync(CreateMockClient(endpoint,subscription),subscription);}
public static Clients CreateMockClient(string e,string sub){var u=new Uri(E(e));var t=new Uri(new UriBuilder(u){Scheme=Uri.UriSchemeHttps,Port=u.Port}.Uri.AbsoluteUri);var m=new MC();return new Clients(new DataFactoryManagementClient(m,new MH()){SubscriptionId=sub,BaseUri=t},new ComputeManagementClient(m,new MH()){SubscriptionId=sub,BaseUri=t});}static string E(string v)=>v.EndsWith("/")?v:v+"/";sealed class MH:DelegatingHandler{protected override Task<HttpResponseMessage>SendAsync(HttpRequestMessage r,CancellationToken t){r.RequestUri=new UriBuilder(r.RequestUri){Scheme=Uri.UriSchemeHttp,Port=r.RequestUri.Port}.Uri;return base.SendAsync(r,t);}}sealed class MC:ServiceClientCredentials{public override Task ProcessHttpRequestAsync(HttpRequestMessage r,CancellationToken t)=>Task.CompletedTask;}}}
